  /** define Results */
  function p_Results(t: T): void {
    t.clearEffects();
    t.setDirection(90);
    t.setXY(0, 0);
    t.switchCostume("ResultsBack1");
    rt.createClone(t, "_myself_");
    t.switchCostume("ResultsBack2");
    rt.createClone(t, "_myself_");
    if (lt(G.v.memory, "6")) {
      if (eq(item(G.l.scores, "1"), "0")) {
        G.v.whoWon = "2";
        t.switchCostume(("Render" + String(G.v.char2)));
        if (eq(G.v.char1, G.v.char2)) {
          t.setEffect("color", "100");
        }
        if (eq(G.v.char2, "45")) {
          t.switchCostume("KuppaWin");
        }
      } else {
        G.v.whoWon = "1";
        t.switchCostume(("Render" + String(G.v.char1)));
      }
    } else {
      if (gt(item(G.l.scores, "2"), item(G.l.scores, "1"))) {
        G.v.whoWon = "2";
        t.switchCostume(("Render" + String(G.v.char2)));
        if (eq(G.v.char1, G.v.char2)) {
          t.setEffect("color", "100");
        }
        if (eq(G.v.char2, "45")) {
          t.switchCostume("KuppaWin");
        }
      } else {
        G.v.whoWon = "1";
        t.switchCostume(("Render" + String(G.v.char1)));
      }
    }
    t.setSize(151);
    t.setXY(-999, 215);
    rt.createClone(t, "_myself_");
    t.setEffect("color", "0");
    t.switchCostume("Wins");
    t.setXY(0, 0);
    t.setSize(100);
    rt.createClone(t, "_myself_");
    if (eq(G.v.whoWon, "1")) {
      if (eq(G.v.char1, "48")) {
        rt.startSound(t, "Maniac2");
      }
    } else {
      if (eq(G.v.char2, "48")) {
        rt.startSound(t, "Maniac2");
      }
    }
    if (eq(G.v.whoWon, "1")) {
      if (eq(G.v.char1, "45")) {
        t.switchCostume("KuppaWin");
        rt.createClone(t, "_myself_");
        rt.startSound(t, "kuppa win");
      }
    } else {
      if (eq(G.v.char2, "45")) {
        t.switchCostume("KuppaWin");
        rt.createClone(t, "_myself_");
        rt.startSound(t, "kuppa win");
      }
    }
    t.switchCostume("nil");
  }

  /** define encodeName %s */
  function p_encodeName(t: T, a_Name: Value): void {
    t.v.code = "";
    t.v.n1 = "1";
    for (let i5 = Math.round(String(a_Name).length); i5-- > 0; ) {
      t.v.code = (String(t.v.code) + String(indexOf(G.l.chars, letterOf(t.v.n1, a_Name))));
      t.v.n1 = num(t.v.n1) + 1;
    }
  }

  /** define decodeName %s */
  function p_decodeName(t: T, a_Name: Value): void {
    t.v.code = "";
    t.v.n1 = "1";
    for (let i6 = Math.round(num((String(a_Name).length / 2))); i6-- > 0; ) {
      t.v.code = (String(t.v.code) + String(item(G.l.chars, (letterOf(t.v.n1, a_Name) + letterOf((num(t.v.n1) + 1), a_Name)))));
      t.v.n1 = num(t.v.n1) + 2;
    }
  }

