  /** define findgimmickUI %s */
  function p_findgimmickUI(t: T, a_1_2: Value): void {
    t.setXY(0, 0);
    if (eq(G.v.char1, "48")) {
      G.v.gimmick1 = "1";
    }
    if (eq(G.v.char2, "48")) {
      G.v.gimmick2 = "1";
    }
    if (eq(a_1_2, "1")) {
      t.setDirection(90);
    } else {
      t.setDirection(-90);
    }
    if ((eq(a_1_2, "1") && eq(G.v.char1, "40"))) {
      G.v.gimmick1 = "10";
    }
    if ((eq(a_1_2, "2") && eq(G.v.char2, "40"))) {
      G.v.gimmick2 = "10";
    }
    if ((eq(a_1_2, "1") && eq(G.v.char1, "27"))) {
      G.v.gimmick1 = "10";
    }
    if ((eq(a_1_2, "2") && eq(G.v.char2, "27"))) {
      G.v.gimmick2 = "10";
    }
    if (((eq(a_1_2, "1") && eq(G.v.char1, "9")) || (eq(a_1_2, "2") && eq(G.v.char2, "9")))) {
      t.setDirection(90);
      t.switchCostume((String(a_1_2) + "NinjaGUI1"));
    } else {
      if ((eq(a_1_2, "1") && !eq(item(t.l.UIcheck, G.v.char1), ""))) {
        t.switchCostume(item(t.l.UIcheck, G.v.char1));
      } else {
        if ((eq(a_1_2, "2") && !eq(item(t.l.UIcheck, G.v.char2), ""))) {
          t.switchCostume(item(t.l.UIcheck, G.v.char2));
        }
      }
    }
    if (!eq(t.costumeName(), "nil")) {
      rt.createClone(t, "_myself_");
      t.switchCostume("nil");
    }
    t.setDirection(90);
    t.setXY(0, 0);
  }

